import sys, random, time, traceback
sys.path.insert(0, '/workspace/submission')
from compiler import compile_plan

def check(n, links, parts, env, period, plan, cut):
    dem=dict(parts); C=set(dem); D=sum(dem.values()); budgets={(l,d):0 for l in range(len(links)) for d in range(2)}
    for l,b in env:
        for d in range(2): budgets[l,d]=period*b
    if cut is not None:
        S=set(cut)
        assert C&S and C-S
        assert sum(period*b for l,b in env if (links[l][0] in S)!=(links[l][1] in S)) < sum(r for v,r in parts if v in S)
        return
    roots=dict.fromkeys(C,0); loads={}; RL={}; phys={}
    for root,count,es in plan['trees']:
        assert root in C and 0<count<=D and len(es)==len(C)-1
        roots[root]+=count
        indeg=dict.fromkeys(C,0); reach={root}
        for u,v in es:
            assert u in C and v in C and u!=v
            indeg[v]+=1
            loads[u,v]=loads.get((u,v),0)+count
        assert indeg[root]==0 and all(indeg[v]==1 for v in C-{root})
        while True:
            old=len(reach)
            for u,v in es:
                if u in reach: reach.add(v)
            if old==len(reach): break
        assert reach==C
    assert roots==dem
    R=plan['recipes']; types=[]; counts=[0]*len(R)
    for i,node in enumerate(R):
        if node[0]==0:
            _,l,d=node; u,v=links[l]
            types.append((u,v) if d==0 else (v,u))
        else:
            _,a,b=node
            assert a<i and b<i
            assert types[a][1]==types[b][0] and types[a][1] not in C
            types.append((types[a][0],types[b][1]))
    for u,v,count,k in plan['routes']:
        assert types[k]==(u,v) and 0<count<=D
        RL[u,v]=RL.get((u,v),0)+count
        counts[k]+=count
    assert RL==loads
    for i in range(len(R)-1,-1,-1):
        node=R[i]
        if node[0]==0:
            key=tuple(node[1:]); phys[key]=phys.get(key,0)+counts[i]
        else:
            counts[node[1]]+=counts[i]; counts[node[2]]+=counts[i]
    assert all(c<=budgets[k] for k,c in phys.items()), (phys,budgets)

def run(seed, Nmax=10):
    random.seed(seed)
    n=random.randint(2,Nmax)
    links=[(u,v) for u in range(n) for v in range(u+1,n) if random.random()<random.random()]
    env=[[l,random.randint(1,12)] for l in range(len(links)) if random.random()<0.95]
    C=random.sample(range(n), random.randint(2,min(n,8)))
    parts=[[v,random.randint(0,10)] for v in C]
    if not sum(r for v,r in parts): parts[0][1]=1
    period=random.randint(1,5)
    try:
        plan, cut=compile_plan(n, links, parts, env, period)
        check(n,links,parts,env,period,plan,cut)
    except BaseException:
        print('FAIL',seed, n,links,parts,env,period,flush=True)
        raise
    return cut is None

if __name__=='__main__':
    start=time.time(); yes=0
    for i in range(int(sys.argv[1]) if len(sys.argv)>1 else 1000):
        yes+=run(i)
        if i%1000==0: print(i,yes,time.time()-start,flush=True)
    print('all passed',yes,time.time()-start)
